package com.dormrepair.file.job;import com.dormrepair.config.FileUploadProperties;import com.dormrepair.file.service.FileService;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(prefix="app.file-upload",name="cleanup-enabled",havingValue="true",matchIfMissing=true) public class OrphanFileCleanupJob {private final FileService service;private final FileUploadProperties props;public OrphanFileCleanupJob(FileService s,FileUploadProperties p){service=s;props=p;}@Scheduled(fixedDelayString="${app.file-upload.cleanup-delay-ms:3600000}")public void cleanup(){service.cleanupExpiredOrphans(props.cleanupBatchSize());}}
